/**
 * Labels — every user-visible string the renderer emits
 * (Phase 49C / v1.32.0 / PHASE-42-STORAGE-ABSTRACTION-01).
 *
 * Mirrors the Python ``Labels`` dataclass at
 * ``plugins/.../learning-repo/adaptive_learner_learning_repo/
 * labels.py`` — field-for-field with the same English
 * defaults so a missing i18n key falls back to identical text
 * on either side.
 *
 * The ``labelsFor(language)`` factory reads the bundled
 * ``frontend/src/data/i18n/{lang}.json`` (regenerated by
 * ``scripts/sync_i18n_to_frontend.py`` from the canonical
 * backend YAML catalogs) and overlays the ``repo.{field}``
 * keys onto the defaults. Identical contract to the Python
 * ``labels_for(language)``: missing keys fall back, malformed
 * input returns defaults.
 */

// --- The label record --------------------------------------------------

/**
 * Every string the renderer emits, grouped by meta-file. The
 * ``{topic}``-style placeholders are substituted by the
 * renderer via ``formatLabel``. Default values exactly match
 * the Python ``@dataclass(frozen=True)`` defaults — the
 * parity test (49F) pins byte-for-byte output on shared
 * input.
 */
export interface Labels {
    // README.md
    readme_title: string;
    readme_goal_heading: string;
    readme_status_heading: string;
    readme_active: string;
    readme_archived: string;
    readme_progress_heading: string;
    readme_sessions_label: string;
    readme_cycles_label: string;
    readme_method_distribution_heading: string;
    readme_topics_heading: string;
    readme_no_topics: string;
    readme_see_also_heading: string;
    readme_see_stats: string;
    readme_see_cheatsheet: string;
    readme_see_roadmap: string;

    // LEARNING_STATS.md
    stats_title: string;
    stats_intro: string;
    stats_no_sessions: string;
    stats_sessions_heading: string;
    stats_table_session: string;
    stats_table_method: string;
    stats_table_understanding: string;
    stats_table_transfer: string;
    stats_table_stress: string;
    stats_table_cycles: string;
    stats_table_status: string;
    stats_method_switches_heading: string;
    stats_no_method_switches: string;
    stats_table_from: string;
    stats_table_to: string;
    stats_table_reason: string;
    stats_table_when: string;
    stats_exit_threshold_heading: string;
    stats_exit_threshold_body: string;
    stats_exit_pin_marker: string;

    // CHEATSHEET.md
    cheatsheet_title: string;
    cheatsheet_intro: string;
    cheatsheet_notes_heading: string;
    cheatsheet_meta_learning_heading: string;
    cheatsheet_no_notes: string;
    cheatsheet_no_meta_learning: string;

    // ROADMAP.md
    roadmap_title: string;
    roadmap_intro: string;
    roadmap_next_steps_heading: string;
    roadmap_no_next_steps: string;
    roadmap_resume_active: string;
    roadmap_start_first: string;
    roadmap_start_next: string;
    roadmap_open_topics_heading: string;
    roadmap_no_open_topics: string;

    // Topic folder stub README.md
    topic_readme_title: string;
    topic_readme_sessions_heading: string;
    topic_readme_methods_heading: string;
    topic_readme_parent_link: string;
    topic_readme_no_sessions: string;
}

