// --- Factory ----------------------------------------------------------

/**
 * Return the Labels bundle for ``language``. Overlay
 * ``repo.{field}`` entries from the bundled i18n catalog onto
 * the English defaults. Missing keys / missing language /
 * malformed catalog fall back silently — matches the Python
 * factory's robustness contract.
 *
 * The bundled JSON catalogs at
 * ``frontend/src/data/i18n/{lang}.json`` are the source of
 * truth at runtime in Dexie mode; they are regenerated from
 * the backend YAML by ``scripts/sync_i18n_to_frontend.py``
 * (drift-pinned by ``i18n-sync.test.ts``).
 */
export async function labelsFor(language: string): Promise<Labels> {
    // Lazy (non-eager) glob: each language catalog is its own
    // chunk fetched on demand, shared with ``dexieStorage.i18n.get``.
    // Eager loading pulled all 8 catalogs into the consuming chunk —
    // see docs/audits/performance-audit-2026-06-03.md F-1.
    // Stryker disable all: static arguments required by Vite's import.meta.glob
    // macro; mutating any part breaks the vite:import-glob parser (#1956).
    const catalogs = import.meta.glob<Record<string, unknown>>(
        "../../data/i18n/*.json",
        {import: "default"},
    );
    // Stryker restore all
    const loader =
        catalogs[`../../data/i18n/${language}.json`] ??
        catalogs["../../data/i18n/en.json"];
    const catalog = loader ? await loader() : undefined;
    if (!catalog) {
        return {...DEFAULT_LABELS};
    }
    const repoBlock = catalog.repo;
    if (!repoBlock || typeof repoBlock !== "object" || Array.isArray(repoBlock)) {
        return {...DEFAULT_LABELS};
    }
    const overrides = repoBlock as Record<string, unknown>;
    const merged: Labels = {...DEFAULT_LABELS};
    for (const key of Object.keys(DEFAULT_LABELS) as (keyof Labels)[]) {
        const value = overrides[key as string];
        if (typeof value === "string") {
            merged[key] = value;
        }
    }
    return merged;
}

// --- Placeholder helper -----------------------------------------------

/**
 * Substitute ``{name}`` placeholders in a label template.
 * Mirrors Python's ``str.format(**kwargs)`` for the limited
 * subset the renderer uses (named, single-level, no format
 * specifiers).
 *
 * Unknown placeholders are left untouched — matches Python's
 * behaviour of raising ``KeyError`` only when the placeholder
 * is referenced and missing; here we silently skip to keep
 * the renderer robust against label-template typos.
 */
export function formatLabel(
    template: string,
    values: Record<string, string | number>,
): string {
    return template.replace(
        /\{(\w+)\}/g,
        (match, name: string) => {
            const v = values[name];
            return v === undefined ? match : String(v);
        },
    );
}
